SET @prov_c := '%s';
SET	@id:= '%s';
SET @cat_id := '%s';
SET	@send :=  IF((SELECT active FROM sys_report WHERE cat_id = @cat_id and id = @id )=1,0,2);
SET @b_year:=(SELECT yearprocess FROM pk_byear LIMIT 1);
SET	@start_d:=concat(@b_year-1,'1001');
SET @end_d:=concat(@b_year,'0930');

CREATE TABLE IF NOT EXISTS s_kpi_dental1(
  id varchar(32) NOT NULL,
  hospcode varchar(5) NOT NULL,
  areacode varchar(8) NOT NULL,
  flag_sent varchar(1) DEFAULT NULL,
  date_com varchar(14) DEFAULT NULL,
  b_year varchar(4) NOT NULL,
	target int(9) DEFAULT 0,
	result int(9) DEFAULT 0,
	PRIMARY KEY (id,hospcode,areacode,b_year),
	KEY (hospcode),
	KEY (areacode),
	KEY (b_year)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

DELETE FROM s_kpi_dental1 WHERE id=@id AND b_year=(@b_year+543);

INSERT IGNORE INTO s_kpi_dental1 
(
SELECT
  @id,t1.hospcode,t1.check_vhid,@send,DATE_FORMAT(now(),'%Y%m%d%H%i%s') as d_com,@b_year+543 as b_year
  ,t1.target,t2.result
FROM (
				SELECT check_hosp hospcode,check_vhid,COUNT(DISTINCT cid) target 
				FROM t_person_cid WHERE check_typearea in(1,3) AND DISCHARGE in(9)
				GROUP BY check_hosp,check_vhid
				)  t1
			LEFT JOIN 
			(SELECT check_hosp hospcode,check_vhid,COUNT(DISTINCT p.cid) result
				FROM tmp_procedure_opd p 
				INNER JOIN cwh_dent_icd10tm i ON p.PROCEDCODE=i.ICD10TM 
				INNER JOIN t_person_cid pe ON pe.cid=p.cid
		   WHERE check_typearea in(1,3) AND DISCHARGE in(9) AND DATE_SERV BETWEEN @start_d AND @end_d 
				GROUP BY check_hosp,check_vhid
      ) as t2 ON t1.hospcode = t2.hospcode AND t1.check_vhid=t2.check_vhid
GROUP BY t1.HOSPCODE,t1.check_vhid
);
